  </p>

  <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-top: 15px;">
    <!-- Panel de Discretización (Binning) -->
    <div style="background: #f6f8fa; padding: 15px; border-radius: 6px; border: 1px solid #e1e4e8;">
      <h4 style="margin-top: 0; color: #8250df;">1. Discretización de Precios (Item_MRP)</h4>
      <p style="font-size: 0.8em; color: #57606a;">Valores de muestra: [35, 48, 52, 98, 105, 112, 145, 160, 185, 210, 240, 250]</p>

      <div style="margin-bottom: 10px;">
        <label style="font-size: 0.85em; font-weight: bold;">Tipo de Partición:</label>
        <div style="margin-top: 4px;">
          <label style="margin-right: 12px; font-size: 0.85em;"><input type="radio" name="binType" value="width" checked> Equal-Width (Igual Ancho)</label>
          <label style="font-size: 0.85em;"><input type="radio" name="binType" value="freq"> Equal-Frequency (Cuantiles)</label>
        </div>
      </div>

      <div style="margin-bottom: 10px;">
        <label style="font-size: 0.85em; font-weight: bold;">Número de Bins ($k$): <span id="kBinVal" style="color: #8250df;">3</span></label>
        <input type="range" id="kBinSlider" min="2" max="5" value="3" style="width: 100%;">
      </div>

      <div style="margin-bottom: 12px;">
        <label style="font-size: 0.85em; font-weight: bold;">Método de Suavizado:</label>
        <select id="smoothMethod" style="width: 100%; padding: 4px; font-size: 0.85em; margin-top: 4px;">
          <option value="none">Sin suavizar (mostrar intervalos)</option>
          <option value="mean">Por Medias del Bin</option>
          <option value="median">Por Medianas del Bin</option>
          <option value="boundary">Por Límites del Bin</option>
        </select>
      </div>

      <div id="binResultContainer" style="max-height: 180px; overflow-y: auto; background: white; border: 1px solid #e1e4e8; border-radius: 4px; padding: 8px; font-size: 0.8em;"></div>
      <p id="binCheck" role="status" aria-live="polite" style="font-size: 0.8em; margin-bottom: 0;"></p>
    </div>

    <!-- Panel de Suavizado Continuo -->
    <div style="background: #f6f8fa; padding: 15px; border-radius: 6px; border: 1px solid #e1e4e8;">
      <h4 style="margin-top: 0; color: #0969da;">2. Filtro de Ruido en Ventas Diarias</h4>
      <div style="margin-bottom: 10px;">
        <label style="font-size: 0.85em; font-weight: bold;">Tipo de Filtro:</label>
        <select id="filterType" style="width: 100%; padding: 4px; font-size: 0.85em; margin-top: 4px;">
          <option value="sma">Media Móvil Simple (SMA)</option>
          <option value="ewma">Suavizado Exponencial (EWMA)</option>
        </select>
      </div>

      <div style="margin-bottom: 10px;">
        <label style="font-size: 0.85em; font-weight: bold;">Ventana / Suavidad: <span id="windowVal" style="color: #0969da;">5</span></label>
        <input type="range" id="windowSlider" min="3" max="11" step="2" value="5" style="width: 100%;">
      </div>

      <!-- SVG Canvas interactivo -->
      <div style="background: white; border: 1px solid #e1e4e8; border-radius: 4px; padding: 6px; text-align: center;">
        <svg id="seriesSvg" width="100%" height="160" viewBox="0 0 300 160" style="display: block;"></svg>
        <div style="font-size: 0.75em; color: #57606a; margin-top: 4px;">
          <span style="color: #8c959f; font-weight: bold;">— Original Ruidosa</span> | 
          <span style="color: #1f2328; font-weight: bold;">--- Tendencia Real</span> | 
          <span style="color: #0969da; font-weight: bold;">— Señal Filtrada</span>
        </div>
      </div>
      <div id="filterInsight" role="status" aria-live="polite" style="margin-top: 8px; font-size: 0.78em; color: #57606a; background: #ddf4ff; padding: 6px; border-radius: 4px; border-left: 3px solid #0969da;"></div>
      <p id="filterCheck" role="status" aria-live="polite" style="font-size: 0.8em; margin-bottom: 0;"></p>
    </div>
  </div>
</div>

<script>
(function() {
  const prices = [35, 48, 52, 98, 105, 112, 145, 160, 185, 210, 240, 250];

  function updateBinning() {
    const k = parseInt(document.getElementById('kBinSlider').value);
    document.getElementById('kBinVal').innerText = k;
    const type = document.querySelector('input[name="binType"]:checked').value;
    const method = document.getElementById('smoothMethod').value;
    const container = document.getElementById('binResultContainer');

    let bins = [];
    if (type === 'width') {
      const min = Math.min(...prices);
      const max = Math.max(...prices);
      const w = (max - min) / k;
      for (let i = 0; i < k; i++) {
        const bMin = min + i * w;
        const bMax = (i === k - 1) ? max : min + (i + 1) * w;
        const items = prices.filter(p => i === k - 1 ? (p >= bMin && p <= bMax) : (p >= bMin && p < bMax));
        bins.push({ label: `[${bMin.toFixed(1)}, ${bMax.toFixed(1)}]`, items: items });
      }
    } else {
      const base = Math.floor(prices.length / k);
      const extra = prices.length % k;
      let offset = 0;
      for (let i = 0; i < k; i++) {
        const size = base + (i < extra ? 1 : 0);
        const items = prices.slice(offset, offset + size);
        offset += size;
        if (items.length > 0) {
          bins.push({ label: `Cuantil ${i+1} (${items.length} items)`, items: items });
        }
      }
    }

    let html = '<table style="width: 100%; border-collapse: collapse;">';
    bins.forEach((b, idx) => {
      let smoothed = [];
      if (b.items.length === 0) {
        smoothed = [];
      } else if (method === 'none') {
        smoothed = b.items;
      } else if (method === 'mean') {
        const m = b.items.reduce((a,c)=>a+c,0) / b.items.length;
        smoothed = b.items.map(() => m.toFixed(1));
      } else if (method === 'median') {
        const mid = Math.floor(b.items.length / 2);
        const med = b.items.length % 2 !== 0 ? b.items[mid] : (b.items[mid-1] + b.items[mid]) / 2;
        smoothed = b.items.map(() => med.toFixed(1));
      } else if (method === 'boundary') {
        const minVal = b.items[0];
        const maxVal = b.items[b.items.length - 1];
        smoothed = b.items.map(val => (Math.abs(val - minVal) < Math.abs(val - maxVal)) ? minVal : maxVal);
      }

      html += `
        <tr style="border-bottom: 1px solid #e1e4e8;">
          <td style="padding: 4px; font-weight: bold; color: #8250df;">${b.label}</td>
          <td style="padding: 4px; color: #24292f;">${b.items.join(', ')}</td>
        </tr>
      `;
      if (method !== 'none' && b.items.length > 0) {
        html += `
          <tr style="border-bottom: 2px solid #eaeef2; background: #fdf8ff;">
            <td style="padding: 3px; font-size: 0.9em; color: #57606a;">↳ Suavizado:</td>
            <td style="padding: 3px; font-size: 0.9em; font-weight: bold; color: #8250df;">[${smoothed.join(', ')}]</td>
          </tr>
        `;
      }
    });
    html += '</table>';
    container.innerHTML = html;
    const counts = bins.map(b => b.items.length);
    const total = counts.reduce((a, b) => a + b, 0);
    document.getElementById('binCheck').innerText =
      `Comprobación: ${total} de ${prices.length} precios asignados; tamaños de grupo: ${counts.join(', ')}.`;
  }

  // Serie de tiempo simulada de ventas (25 puntos)
  const N_POINTS = 25;
  const trueSignal = [];
  const noisySignal = [];
  for (let i = 0; i < N_POINTS; i++) {
    const t = i / (N_POINTS - 1) * Math.PI * 2;
    const base = Math.sin(t) * 40 + 80;
    trueSignal.push(base);
    // Ruido pseudoaleatorio determinista
    const noise = Math.sin(i * 3.7) * 18 + Math.cos(i * 1.9) * 8;
    noisySignal.push(base + noise);
  }

  function updateFilter() {
    const filter = document.getElementById('filterType').value;
    const w = parseInt(document.getElementById('windowSlider').value);
    document.getElementById('windowVal').innerText = w;

    let filtered = [];
    if (filter === 'sma') {
      const half = Math.floor(w / 2);
      for (let i = 0; i < N_POINTS; i++) {
        let sum = 0, count = 0;
        for (let j = -half; j <= half; j++) {
          const idx = i + j;
          if (idx >= 0 && idx < N_POINTS) {
            sum += noisySignal[idx];
            count++;
          }
        }
        filtered.push(sum / count);
      }
      document.getElementById('filterInsight').innerText = `Media Móvil con ventana=${w}. Observa cómo suaviza el ruido pero puede atenuar (aplanar) el pico máximo.`;
    } else if (filter === 'ewma') {
      const alpha = 2.0 / (w + 1);
      let s = noisySignal[0];
      filtered.push(s);
      for (let i = 1; i < N_POINTS; i++) {
        s = alpha * noisySignal[i] + (1 - alpha) * s;
        filtered.push(s);
      }
      document.getElementById('filterInsight').innerText = `EWMA con α=${alpha.toFixed(2)}. Da más peso al dato reciente; introduce cierto desfase temporal causal.`;
    }

    // Dibujar SVG
    const svg = document.getElementById('seriesSvg');
    const width = 300, height = 150;
    const pad = 15;
    const minVal = 20, maxVal = 140;

    function getX(i) { return pad + (i / (N_POINTS - 1)) * (width - 2 * pad); }
    function getY(val) { return height - pad - ((val - minVal) / (maxVal - minVal)) * (height - 2 * pad); }

    function makePath(data) {
      return data.map((d, i) => `${i === 0 ? 'M' : 'L'} ${getX(i).toFixed(1)} ${getY(d).toFixed(1)}`).join(' ');
    }

    svg.innerHTML = `
      <path d="${makePath(noisySignal)}" fill="none" stroke="#d0d7de" stroke-width="2" stroke-linecap="round"/>
      <path d="${makePath(trueSignal)}" fill="none" stroke="#1f2328" stroke-width="2" stroke-dasharray="4,4"/>
      <path d="${makePath(filtered)}" fill="none" stroke="#0969da" stroke-width="2.5" stroke-linecap="round"/>
    `;
    const rmse = values => Math.sqrt(values.reduce((sum, value, i) =>
      sum + Math.pow(value - trueSignal[i], 2), 0) / N_POINTS);
    document.getElementById('filterCheck').innerText =
      `Error frente a la señal simulada (RMSE): sin filtro ${rmse(noisySignal).toFixed(1)}; con filtro ${rmse(filtered).toFixed(1)}. Una ventana no siempre mejora este valor.`;
  }

  document.getElementById('kBinSlider').addEventListener('input', updateBinning);
  document.querySelectorAll('input[name="binType"]').forEach(r => r.addEventListener('change', updateBinning));
  document.getElementById('smoothMethod').addEventListener('change', updateBinning);

  document.getElementById('filterType').addEventListener('change', updateFilter);
  document.getElementById('windowSlider').addEventListener('input', updateFilter);

  updateBinning();
  updateFilter();
})();
</script>
```
